//! zig-libs tlsclient: the ClientHello's ECDHE key shares without std's
//! `basePoint.mul`, which was ~2/3 of a handshake's client CPU (P-384 ~1.07 ms,
//! P-256 ~0.29 ms on the author's host, 2026-10-11).
//!
//! * P-384: a fixed-base comb over std's `P384`. The table
//!   (`p384_base_table.zig`, generated by `tools/gen_p384_base_table.py`) holds
//!   `(j+1)·2^(5i)·G` in affine form, so `s·G` is 78 mixed additions (std's own
//!   complete `addMixed`) and no doublings. Field, formulas and point type are
//!   std's; only the schedule is new. A stopgap: a full `p384` module (own
//!   field, ECDH, ECDSA) is the tlsclient SPEC's Backlog item, and the comb
//!   moves there when it exists.
//! * P-256: the `p256` module's comb (`P256.combMulBase`).
//!
//! The key pairs are std's `generateDeterministic`, byte for byte: the secret
//! scalar comes from std's derivation (`deterministicSecret`, copied from Zig
//! 0.16 `std/crypto/ecdsa.zig`, MIT), only the public point is computed here.
//!
//! Constant-time in the scalar like `p256.combMulBaseFast` (the pattern the
//! P-384 comb copies): signed 5-bit digits recoded branch-free, every table
//! entry of a window read through masked blends, the sum always computed and
//! kept by a mask; masks laundered through `blackBox` so LLVM cannot turn them
//! back into branches or secret-indexed loads. Measured by ctgrind row
//! `tlsclient/kex`.

const std = @import("std");
const crypto = std.crypto;
const P384 = crypto.ecc.P384;
const Fe = P384.Fe;
const AffineCoordinates = @TypeOf(P384.basePoint.affineCoordinates());
const Ecdsa = crypto.sign.ecdsa.EcdsaP384Sha384;
const EcdsaP256 = crypto.sign.ecdsa.EcdsaP256Sha256;
const p256 = @import("p256");
const IdentityElementError = crypto.errors.IdentityElementError;

pub const BaseTable = [windows][teeth]AffineCoordinates;
pub const base_table: BaseTable = @import("p384_base_table.zig").table;

const w = 5;
const teeth = 1 << (w - 1); // |digit| ≤ 16
/// 78 windows: 77 cover the 384 bits (the 77th holds bits 380..383), the 78th
/// takes the last signed-digit carry.
const windows = 78;
comptime {
    std.debug.assert(windows * w >= 384 + 1);
}

/// `s·G` for a big-endian scalar, constant-time in `s`, equal to std's
/// `P384.basePoint.mul(s, .big)` (any 384-bit `s`; the group order reduces it).
/// `error.IdentityElement` iff `s ≡ 0 (mod n)`, as std.
pub fn mulBase(s: [48]u8) IdentityElementError!P384 {
    return mulBaseWithTable(&base_table, s);
}

/// `mulBase` over a given table — the corrupted-table control in the tests.
/// Table indices are driven by loop counters only, never by the scalar.
pub fn mulBaseWithTable(tab: *const BaseTable, s: [48]u8) IdentityElementError!P384 {
    var acc = P384.identityElement;
    var carry: u32 = 0;
    for (0..windows) |i| {
        // Bits 5i..5i+4 of the big-endian scalar: a 16-bit little-endian
        // window over the two bytes holding them. Positions are public.
        const bit = i * w;
        const lo_byte = bit / 8;
        const b0: u32 = if (lo_byte < 48) s[47 - lo_byte] else 0;
        const b1: u32 = if (lo_byte + 1 < 48) s[46 - lo_byte] else 0;
        const wv = ((b0 | (b1 << 8)) >> @intCast(bit % 8)) & ((1 << w) - 1);
        const x = wv + carry; // 0 .. 2^w
        const is_neg: u32 = @intFromBool(x >= teeth);
        carry = is_neg;
        const negmask: u64 = blackBox(0 -% @as(u64, is_neg));
        const x64: u64 = x;
        const m = (((1 << w) - x64) & negmask) | (x64 & ~negmask); // |digit|, 0 .. 16

        // Digit 0 keeps the window's first entry (a public index), a valid
        // point whose sum the `keep` mask discards — never the affine (0, 0):
        // std's `addMixed` selects on `q.x.isZero()` with a `cMov` that
        // ctgrind saw lowered to a secret-dependent load (2026-10-11), which is
        // why `addMixedComplete` below is a copy without that select.
        var g = tab[i][0];
        for (1..teeth) |j| {
            const mask = blackBox(0 -% @as(u64, @intFromBool(@as(u64, j + 1) == m)));
            blend(&g.x, tab[i][j].x, mask);
            blend(&g.y, tab[i][j].y, mask);
        }
        blend(&g.y, g.y.neg(), blackBox(0 -% @as(u64, is_neg)));

        // Always add; keep the sum iff the digit was nonzero. The formula is
        // complete for any projective `acc` (the identity included) and any
        // affine `g` on the curve.
        const sum = addMixedComplete(acc, g);
        const keep = blackBox(0 -% @as(u64, @intFromBool(m != 0)));
        blend(&acc.x, sum.x, keep);
        blend(&acc.y, sum.y, keep);
        blend(&acc.z, sum.z, keep);
    }
    // `carry` is 0 here: the 78th window reads no scalar bits, so its x is
    // the previous carry (0 or 1) < 16. No runtime check — it is secret-derived.
    try acc.rejectIdentity();
    return acc;
}

/// std's `EcdsaP384Sha384.KeyPair.generateDeterministic(seed)`, byte for
/// byte, with the public key from `mulBase`.
pub fn keyPairP384(seed: [Ecdsa.KeyPair.seed_length]u8) IdentityElementError!Ecdsa.KeyPair {
    const sk = deterministicSecret(Ecdsa, P384, crypto.hash.sha2.Sha384, seed);
    return .{ .secret_key = .{ .bytes = sk }, .public_key = .{ .p = try mulBase(sk) } };
}

/// std's `EcdsaP256Sha256.KeyPair.generateDeterministic(seed)`, byte for
/// byte, with the public key from `p256.P256.combMulBase` (converted to std's
/// point through its SEC1 encoding, a public value).
pub fn keyPairP256(seed: [EcdsaP256.KeyPair.seed_length]u8) IdentityElementError!EcdsaP256.KeyPair {
    const sk = deterministicSecret(EcdsaP256, crypto.ecc.P256, crypto.hash.sha2.Sha256, seed);
    const q = try p256.P256.combMulBase(sk, .big);
    // The public key goes out in the ClientHello: declassified for ctgrind
    // before std's parser branches on it (a no-op without `-fvalgrind`).
    const sec1 = q.toUncompressedSec1();
    std.valgrind.memcheck.makeMemDefined(&sec1);
    const p = crypto.ecc.P256.fromSec1(&sec1) catch unreachable; // a valid point by construction
    return .{ .secret_key = .{ .bytes = sk }, .public_key = .{ .p = p } };
}

/// The secret scalar of std's `Ecdsa(Curve, Hash).KeyPair.generateDeterministic`:
/// its private `deterministicScalar(h = 0^digest, x = 0x01^scalar, noise = seed)`
/// — copied from Zig 0.16 `std/crypto/ecdsa.zig` (MIT); the differential
/// tests pin the two together.
fn deterministicSecret(comptime E: type, comptime Curve: type, comptime Hash: type, seed: [E.KeyPair.seed_length]u8) [Curve.scalar.encoded_length]u8 {
    const Prf = crypto.auth.hmac.Hmac(Hash);
    const sl = Curve.scalar.encoded_length;
    const nl = E.noise_length;
    const h = [_]u8{0x00} ** Hash.digest_length;
    const x = [_]u8{0x01} ** sl;

    var k = [_]u8{0x00} ** h.len;
    var m = [_]u8{0x00} ** (h.len + 1 + nl + x.len + h.len);
    var t = [_]u8{0x00} ** sl;
    defer crypto.secureZero(u8, &k);
    defer crypto.secureZero(u8, &m);
    defer crypto.secureZero(u8, &t);
    const m_v = m[0..h.len];
    const m_i = &m[m_v.len];
    const m_z = m[m_v.len + 1 ..][0..nl];
    const m_x = m[m_v.len + 1 + nl ..][0..x.len];
    const m_h = m[m.len - h.len ..];
    @memset(m_v, 0x01);
    m_i.* = 0x00;
    @memcpy(m_z, &seed);
    @memcpy(m_x, &x);
    @memcpy(m_h, &h);
    Prf.create(&k, &m, &k);
    Prf.create(m_v, m_v, &k);
    m_i.* = 0x01;
    Prf.create(&k, &m, &k);
    Prf.create(m_v, m_v, &k);
    while (true) {
        var t_off: usize = 0;
        while (t_off < t.len) : (t_off += m_v.len) {
            const t_end = @min(t_off + m_v.len, t.len);
            Prf.create(m_v, m_v, &k);
            @memcpy(t[t_off..t_end], m_v[0 .. t_end - t_off]);
        }
        if (Curve.scalar.Scalar.fromBytes(t, .big)) |sc| return sc.toBytes(.big) else |_| {}
        m_i.* = 0x00;
        Prf.create(&k, m[0 .. m_v.len + 1], &k);
        Prf.create(m_v, m_v, &k);
    }
}

/// std's `P384.addMixed` (Renes–Costello–Batina 2015, Algorithm 5; copied
/// from Zig 0.16 `std/crypto/pcurves/p384.zig`, MIT) without its final
/// `ret.cMov(p, q.x.isZero())`, the select that makes it return `p` for the
/// affine identity. `q` must be a curve point (the comb never passes another);
/// then the formula is complete and branch-free.
fn addMixedComplete(p: P384, q: AffineCoordinates) P384 {
    const B = P384.B;
    var t0 = p.x.mul(q.x);
    var t1 = p.y.mul(q.y);
    var t3 = q.x.add(q.y);
    var t4 = p.x.add(p.y);
    t3 = t3.mul(t4);
    t4 = t0.add(t1);
    t3 = t3.sub(t4);
    t4 = q.y.mul(p.z);
    t4 = t4.add(p.y);
    var Y3 = q.x.mul(p.z);
    Y3 = Y3.add(p.x);
    var Z3 = B.mul(p.z);
    var X3 = Y3.sub(Z3);
    Z3 = X3.dbl();
    X3 = X3.add(Z3);
    Z3 = t1.sub(X3);
    X3 = t1.add(X3);
    Y3 = B.mul(Y3);
    t1 = p.z.dbl();
    var t2 = t1.add(p.z);
    Y3 = Y3.sub(t2);
    Y3 = Y3.sub(t0);
    t1 = Y3.dbl();
    Y3 = t1.add(Y3);
    t1 = t0.dbl();
    t0 = t1.add(t0);
    t0 = t0.sub(t2);
    t1 = t4.mul(Y3);
    t2 = t0.mul(Y3);
    Y3 = X3.mul(Z3);
    Y3 = Y3.add(t2);
    X3 = t3.mul(X3);
    X3 = X3.sub(t1);
    Z3 = t4.mul(Z3);
    t1 = t3.mul(t0);
    Z3 = Z3.add(t1);
    return .{ .x = X3, .y = Y3, .z = Z3 };
}

inline fn blackBox(v: u64) u64 {
    return asm volatile (""
        : [ret] "=r" (-> u64),
        : [v] "0" (v),
    );
}

/// `dst = (dst & ~mask) | (src & mask)`, `mask` 0 or all ones.
inline fn blend(dst: *Fe, src: Fe, mask: u64) void {
    for (&dst.limbs, src.limbs) |*d, sv| d.* = (sv & mask) | (d.* & ~mask);
}

// ── tests ────────────────────────────────────────────────────────────────

const testing = std.testing;

/// Equal as serialized points. Not `equivalent`: that compares cross
/// products, and the degenerate (0:0:0) — what a comb that adds the dummy
/// (0, 0) to the identity produces — is "equivalent" to every point (a
/// negative control survived on exactly that, 2026-10-11).
fn expectSamePoint(want: P384, got: P384) !void {
    try testing.expect(!got.z.isZero());
    try testing.expectEqualSlices(u8, &want.toUncompressedSec1(), &got.toUncompressedSec1());
}

test "p384 comb: mulBase(s) == std basePoint.mul(s) on edge and random scalars" {
    const n_be = P384.scalar.field_order;
    var cases: [8][48]u8 = undefined;
    cases[0] = [_]u8{0} ** 47 ++ [_]u8{1};
    cases[1] = [_]u8{0} ** 47 ++ [_]u8{2};
    cases[2] = [_]u8{0xff} ** 48; // 2^384 − 1 > n: reduced by the group order
    std.mem.writeInt(u384, &cases[3], n_be - 1, .big);
    std.mem.writeInt(u384, &cases[4], n_be + 1, .big);
    cases[5] = [_]u8{0} ** 48;
    cases[5][0] = 0x80; // 2^383
    cases[6] = [_]u8{0x10} ** 48; // every window's digit 16 → negative digits, carries
    cases[7] = [_]u8{ 0x84, 0x21 } ** 24; // 0b10000 runs: digit = half, the boundary
    for (cases) |s| try expectSamePoint(try P384.basePoint.mul(s, .big), try mulBase(s));

    var prng = std.Random.DefaultPrng.init(0x384_C0B);
    for (0..200) |_| {
        var s: [48]u8 = undefined;
        prng.random().bytes(&s);
        try expectSamePoint(try P384.basePoint.mul(s, .big), try mulBase(s));
    }
    // s ≡ 0 (mod n): both refuse.
    var zero = [_]u8{0} ** 48;
    try testing.expectError(error.IdentityElement, mulBase(zero));
    std.mem.writeInt(u384, &zero, n_be, .big);
    try testing.expectError(error.IdentityElement, mulBase(zero));
}

test "p384 comb: table entries are (j+1)·2^(5i)·G (spot checks against std mulPublic), a corrupted table fails the differential" {
    const spots = [_][2]usize{ .{ 0, 0 }, .{ 0, 15 }, .{ 1, 3 }, .{ 37, 9 }, .{ 76, 0 }, .{ 76, 14 } };
    for (spots) |ij| {
        var s = [_]u8{0} ** 48;
        const v: u384 = (@as(u384, ij[1]) + 1) << @intCast(5 * ij[0]);
        std.mem.writeInt(u384, &s, v, .big);
        const want = (try P384.basePoint.mulPublic(s, .big)).affineCoordinates();
        const got = base_table[ij[0]][ij[1]];
        try testing.expect(got.x.equivalent(want.x));
        try testing.expect(got.y.equivalent(want.y));
    }
    // The 78th window, 2^385·(j+1)·G, does not fit a 384-bit scalar: check it
    // as 32 times the 77th.
    for ([_]usize{ 0, 15 }) |j| {
        var q = try P384.fromAffineCoordinates(base_table[76][j]);
        for (0..5) |_| q = q.dbl();
        const want = q.affineCoordinates();
        try testing.expect(base_table[77][j].x.equivalent(want.x));
        try testing.expect(base_table[77][j].y.equivalent(want.y));
    }
    var bad = base_table;
    bad[40][7].y = bad[40][7].y.neg();
    var s: [48]u8 = undefined;
    @memset(&s, 0);
    std.mem.writeInt(u384, &s, @as(u384, 8) << 200, .big); // digit 8 in window 40
    try testing.expect(!(try mulBaseWithTable(&bad, s)).equivalent(try P384.basePoint.mul(s, .big)));
    try expectSamePoint(try P384.basePoint.mul(s, .big), try mulBaseWithTable(&base_table, s));
}

test "keygen: keyPairP384 / keyPairP256 == std generateDeterministic, byte for byte" {
    var prng = std.Random.DefaultPrng.init(0x5EED_384);
    for (0..64) |_| {
        var seed: [Ecdsa.KeyPair.seed_length]u8 = undefined;
        prng.random().bytes(&seed);
        const want = try Ecdsa.KeyPair.generateDeterministic(seed);
        const got = try keyPairP384(seed);
        try testing.expectEqualSlices(u8, &want.secret_key.bytes, &got.secret_key.bytes);
        try testing.expectEqualSlices(u8, &want.public_key.toUncompressedSec1(), &got.public_key.toUncompressedSec1());

        var seed2: [EcdsaP256.KeyPair.seed_length]u8 = undefined;
        prng.random().bytes(&seed2);
        const want2 = try EcdsaP256.KeyPair.generateDeterministic(seed2);
        const got2 = try keyPairP256(seed2);
        try testing.expectEqualSlices(u8, &want2.secret_key.bytes, &got2.secret_key.bytes);
        try testing.expectEqualSlices(u8, &want2.public_key.toUncompressedSec1(), &got2.public_key.toUncompressedSec1());
    }
}
